<script setup lang="ts">
import {computed,ref,shallowRef,onMounted,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {message,Modal} from 'ant-design-vue';
import {listDatasets,listDatasetVersions,type Dataset,type DatasetVersion} from '@/api/evaluation';
import {listPipelines,listPipelineVersions,getPipeline} from '@/api/pipelines';
import {pipelinePayloadRestricted,type PublishedPipeline,type PipelineVersion} from '@/api/pipeline-policies';
import {usePermission} from '@/composables/permission';
import BenchmarkReportPanel from '@/components/BenchmarkReportPanel.vue';
import ModelConsistencyPanel from '@/components/ModelConsistencyPanel.vue';
import CitationGroundingPanel from '@/components/CitationGroundingPanel.vue';
import {createBenchmark,type BenchmarkDimension} from '@/api/benchmarks';
import {listTasks,getTask,listTaskExecutions,type InspectionTask,type TaskExecutionSummary} from '@/api/tasks';
import {createEvaluationTask,getEvaluationReport,listEvaluationResults,getEvaluationResult,type EvaluationReport,type EvaluationResult} from '@/api/evaluation';
const {can}=usePermission(),route=useRoute(),router=useRouter();
const rows=ref<InspectionTask[]>([]),page=ref(1),total=ref(0),loading=ref(false),error=ref(''),busy=ref(false),createBusy=ref(false),createOpen=ref(false);
const form=ref({name:'',datasetId:'',datasetVersion:1,pipelineId:'',target:'published',targetVersion:1,concurrency:1});
const datasetOptions=ref<Dataset[]>([]),datasetVersions=ref<DatasetVersion[]>([]),datasetPage=ref(1),datasetTotal=ref(0),versionPage=ref(1),versionTotal=ref(0),pipelineOptions=ref<PublishedPipeline[]>([]),pipelineVersions=ref<PipelineVersion[]>([]),pipelinePage=ref(1),pipelineTotal=ref(0),pipelineDraft=ref<number>(),assetBusy=ref(false),assetError=ref('');let assetGeneration=0,datasetGeneration=0,pipelineGeneration=0;
const benchmarkMode=ref(false),dimension=ref<BenchmarkDimension>('FUSION'),variableNodeId=ref<string>(),skillSlot=ref(0),candidateId=ref(''),candidateMode=ref('published'),candidateVersion=ref(0),candidateVersions=ref<PipelineVersion[]>([]),candidateDraft=ref<number>(),baselineDraftJson=ref('');let candidateGeneration=0;
const baselineNodes=computed(()=>{try{const version=pipelineVersions.value.find(v=>v.versionNo===form.value.targetVersion);const raw=form.value.target==='draft'?baselineDraftJson.value:version&&!pipelinePayloadRestricted(version)?version.snapshotJson:null;const release=JSON.parse(raw||'null');return (release?.pipeline?.nodes||[]).filter((n:{type:string})=>n.type==='LLM'||dimension.value==='SKILL'&&n.type==='SKILL_API'||dimension.value==='MODEL'&&n.type==='SMALL_MODEL') as Array<{nodeId:string;name:string;type:string}>;}catch{return [];}});
const needsNode=computed(()=>['PROMPT','MODEL','SKILL'].includes(dimension.value));
const standaloneSkill=computed(()=>dimension.value==='SKILL'&&baselineNodes.value.find(node=>node.nodeId===variableNodeId.value)?.type==='SKILL_API');
watch(baselineNodes,nodes=>{if(variableNodeId.value&&!nodes.some(node=>node.nodeId===variableNodeId.value))variableNodeId.value=undefined;});
watch(standaloneSkill,value=>{if(value)skillSlot.value=0;});
async function chooseCandidate(id:string){candidateId.value=id;candidateVersion.value=0;candidateDraft.value=undefined;candidateVersions.value=[];const ticket=++candidateGeneration;const done=await Promise.allSettled([listPipelineVersions(id).then(d=>{if(ticket===candidateGeneration)candidateVersions.value=d;}),getPipeline(id).then(d=>{if(ticket===candidateGeneration)candidateDraft.value=d.draftRevision;})]);if(ticket===candidateGeneration){if(done.some(r=>r.status==='rejected'))assetError.value='候选版本或草稿加载失败';updateCandidate();}}
function updateCandidate(){candidateVersion.value=candidateMode.value==='draft'?(candidateDraft.value??0):(candidateVersions.value[0]?.versionNo??0);}
watch([dimension,variableNodeId,skillSlot,candidateId,candidateMode,candidateVersion],()=>{if(!createBusy.value)requestId.value=crypto.randomUUID();});
const requestId=ref(''),selected=ref<InspectionTask>(),rounds=ref<TaskExecutionSummary[]>([]),executionId=ref<string>(),report=shallowRef<EvaluationReport>(),results=ref<EvaluationResult[]>([]),resultPage=ref(1),resultTotal=ref(0),detail=ref('');let generation=0,listGeneration=0,detailGeneration=0,resultGeneration=0;
const percent=(value:number|null|undefined)=>value==null?'无分母':`${(value*100).toFixed(2)}%`;
const completenessPercent=(value:number|null|undefined)=>value==null?'未测量':percent(value);
async function refresh(p=1){const ticket=++listGeneration;loading.value=true;error.value='';try{const d=await listTasks({taskType:'PIPELINE_EVALUATION',current:p,size:20});if(ticket===listGeneration){rows.value=d.records;total.value=d.total;page.value=p;}}catch{if(ticket===listGeneration)error.value='评测任务加载失败，请重试。';}finally{if(ticket===listGeneration)loading.value=false;}}
function openCreate(benchmark=false){benchmarkMode.value=benchmark;dimension.value='FUSION';variableNodeId.value=undefined;candidateId.value='';candidateVersions.value=[];candidateDraft.value=undefined;candidateVersion.value=0;candidateMode.value='published';++candidateGeneration;baselineDraftJson.value='';++datasetGeneration;++pipelineGeneration;datasetVersions.value=[];pipelineVersions.value=[];pipelineDraft.value=undefined;versionTotal.value=0;assetError.value='';form.value={name:'',datasetId:typeof route.query.datasetId==='string'?route.query.datasetId:'',datasetVersion:1,pipelineId:'',target:'published',targetVersion:1,concurrency:1};requestId.value=crypto.randomUUID();createOpen.value=true;void loadAssets();if(form.value.datasetId)void chooseDataset(form.value.datasetId);}
async function loadAssets(){const ticket=++assetGeneration;assetBusy.value=true;assetError.value='';const done=await Promise.allSettled([listDatasets(datasetPage.value).then(d=>{if(ticket===assetGeneration){datasetOptions.value=d.records.filter(r=>r.status==='ACTIVE');datasetTotal.value=d.total;}}),listPipelines(pipelinePage.value).then(d=>{if(ticket===assetGeneration){pipelineOptions.value=d.records.filter(r=>r.status==='ACTIVE');pipelineTotal.value=d.total;}})]);if(ticket===assetGeneration){assetBusy.value=false;if(done.some(r=>r.status==='rejected'))assetError.value='资产目录加载失败，请检查目录权限后刷新。';}}
async function chooseDataset(id:string,p=1){form.value.datasetId=id;form.value.datasetVersion=0;datasetVersions.value=[];versionPage.value=p;const ticket=++datasetGeneration;try{const d=await listDatasetVersions(id,p);if(ticket===datasetGeneration){datasetVersions.value=d.records;versionTotal.value=d.total;form.value.datasetVersion=d.records[0]?.versionNo??0;}}catch{if(ticket===datasetGeneration)assetError.value='数据集冻结版本加载失败';}}
async function choosePipeline(id:string){form.value.pipelineId=id;pipelineVersions.value=[];pipelineDraft.value=undefined;baselineDraftJson.value='';form.value.targetVersion=0;const ticket=++pipelineGeneration;const done=await Promise.allSettled([listPipelineVersions(id).then(d=>{if(ticket===pipelineGeneration)pipelineVersions.value=d;}),getPipeline(id).then(d=>{if(ticket===pipelineGeneration){pipelineDraft.value=d.draftRevision;baselineDraftJson.value=pipelinePayloadRestricted(d)?'':d.draftConfigJson??'';}})]);if(ticket===pipelineGeneration){if(done.some(r=>r.status==='rejected'))assetError.value='目标版本或草稿加载失败，请核对读取权限。';updateTarget();}}
function updateTarget(){form.value.targetVersion=form.value.target==='draft'?(pipelineDraft.value??0):(pipelineVersions.value[0]?.versionNo??0);}
function closeCreate(){if(createBusy.value)return;Modal.confirm({title:'关闭创建窗口？',content:'当前填写的评测参数将被放弃。',onOk:()=>{createOpen.value=false;++assetGeneration;++datasetGeneration;++pipelineGeneration;++candidateGeneration;}});}
watch(form,()=>{if(!createBusy.value)requestId.value=crypto.randomUUID();},{deep:true});
async function create(){
 if(createBusy.value||!form.value.datasetId||!form.value.pipelineId||!Number.isInteger(form.value.datasetVersion)||form.value.datasetVersion<1||!Number.isInteger(form.value.targetVersion)||form.value.targetVersion<1)return;
 if(benchmarkMode.value&&(!candidateId.value||candidateVersion.value<1||needsNode.value&&!variableNodeId.value)){message.warning('请选择候选精确版本及变量节点');return;}
 createBusy.value=true;
 try{const f=form.value;const baseline={pipelineId:f.pipelineId,...(f.target==='published'?{pipelineVersion:f.targetVersion}:{draftRevision:f.targetVersion})};let id:string;
 if(benchmarkMode.value){const pair=await createBenchmark({name:f.name.trim()||undefined,datasetId:f.datasetId,datasetVersion:f.datasetVersion,baseline,candidate:{pipelineId:candidateId.value,...(candidateMode.value==='published'?{pipelineVersion:candidateVersion.value}:{draftRevision:candidateVersion.value})},selection:{dimension:dimension.value,...(needsNode.value?{nodeId:variableNodeId.value}:{}),...(dimension.value==='SKILL'&&!standaloneSkill.value?{slot:skillSlot.value}:dimension.value==='MODEL'?{slot:0}:{})},concurrency:f.concurrency,requestId:requestId.value});id=pair.baseline.id;message.success('双侧评测任务已创建，请分别手动执行');}
 else{const task=await createEvaluationTask({name:f.name.trim()||undefined,datasetId:f.datasetId,datasetVersion:f.datasetVersion,...baseline,concurrency:f.concurrency,requestId:requestId.value});id=task.id;message.success('评测任务已创建，请在任务页执行');}
 createOpen.value=false;await refresh();await router.replace({path:'/evaluation/tasks',query:{taskId:id}});
 }catch{message.error('创建未成功，请核对冻结版本、声明变量及权限；原参数重试保留请求标识。');}finally{createBusy.value=false;}
}
const benchmarkBaselineId=computed(()=>{const meta=selected.value?.taskPresentation;if(meta)return meta.schemaVersion==='iqc-task-presentation-v1'?meta.benchmarkBaselineTaskId:undefined;try{const marker=JSON.parse(selected.value?.ruleSnapshotJson||'null')?.benchmarkSnapshot;if(marker?.schemaVersion!=='iqc-benchmark-pair-v1')return undefined;return marker.side==='BASELINE'?selected.value?.id:marker.side==='CANDIDATE'&&typeof marker.peerTaskId==='string'?marker.peerTaskId:undefined;}catch{return undefined;}});
async function loadResults(p=1,ticket=generation){if(!selected.value||!executionId.value||!can('iqc:evaluation:results:view'))return;const request=++resultGeneration;const d=await listEvaluationResults(selected.value.id,executionId.value,p);if(ticket===generation&&request===resultGeneration){results.value=d.records;resultPage.value=p;resultTotal.value=d.total;}}
async function loadRound(){const ticket=++generation;++detailGeneration;report.value=undefined;results.value=[];resultTotal.value=0;detail.value='';busy.value=true;error.value='';try{const id=selected.value?.id;if(!id||!executionId.value){error.value='该评测任务尚未执行，请到任务页执行。';return;}const work:Promise<unknown>[]=[loadResults(1,ticket)];if(can('iqc:evaluation:report:view'))work.push(getEvaluationReport(id,executionId.value).then(d=>{if(ticket===generation)report.value=d;}));const done=await Promise.allSettled(work);if(ticket===generation&&done.some(r=>r.status==='rejected'))error.value='部分评测数据加载失败，请刷新；未执行任务还没有报告。';}finally{if(ticket===generation)busy.value=false;}}
async function selectTask(id:string){const ticket=++generation;busy.value=true;error.value='';report.value=undefined;results.value=[];detail.value='';selected.value=undefined;rounds.value=[];try{const [task,history]=await Promise.all([getTask(id),listTaskExecutions(id)]);if(ticket!==generation)return;if(task.taskType!=='PIPELINE_EVALUATION')throw Error();selected.value=task;rounds.value=history;executionId.value=task.currentExecutionId||history[0]?.id;await loadRound();}catch{if(ticket===generation){error.value='任务加载失败，或该任务不是评测任务。';busy.value=false;}}}
async function viewResult(row:EvaluationResult){
 if(!selected.value)return;
 const ticket=++detailGeneration,id=selected.value.id;detail.value='';
 try{const d=await getEvaluationResult(id,row.id);
  if(ticket!==detailGeneration||selected.value?.id!==id)return;
  const metadata={...d,actualJson:undefined};
  if(d.privacy){
   if(d.privacy.policyVersion!=='iqc-evaluation-read-v1'){detail.value='展示协议不受支持，未显示产物正文。';return;}
   if(d.privacy.canonicalPayloadVisible!==true||d.privacy.canReadFull!==true||d.privacy.canReadPii!==true||d.privacy.canReadPrompt!==true){
    detail.value='受限展示：仅运行摘要，原始变量、事实值和轨迹正文未展示；不能据此视作无命中或重新计算原产物摘要。\n'+JSON.stringify(metadata,null,2);return;
   }
  }
  detail.value=JSON.stringify(metadata,null,2)+(d.actualJson?'\n原始机器产物（保留数值原文）：\n'+d.actualJson:'\n响应未包含机器产物正文。');
 }catch{if(ticket===detailGeneration&&selected.value?.id===id)detail.value='评测产物加载失败，请重新读取。';}
}

function showTask(id:string){void router.replace({path:'/evaluation/tasks',query:{taskId:id}});}
watch(()=>route.query.taskId,id=>{if(typeof id==='string')void selectTask(id);else{++generation;++detailGeneration;++resultGeneration;selected.value=undefined;report.value=undefined;results.value=[];rounds.value=[];detail.value='';busy.value=false;}});
onMounted(()=>{void refresh();if(typeof route.query.taskId==='string')void selectTask(route.query.taskId);});
</script>
<template>
<section class="page-intro"><div><h2>固定数据集评测</h2><p>完整冻结金标进入分母。报告完整表示终态且产物齐全；流水线发布仍须通过独立的发布门禁。</p></div><a-button v-if="can('iqc:evaluation:task:create')" type="primary" @click="openCreate(false)">创建评测任务</a-button><a-button v-if="can('iqc:benchmark:create')" @click="openCreate(true)">创建单变量对照</a-button></section>
<a-alert v-if="error" type="warning" :message="error"/><a-button :loading="loading" @click="refresh(page)">刷新任务</a-button><a-button @click="router.push('/tasks')">任务执行与暂停</a-button>
<a-table :data-source="rows" row-key="id" :pagination="false" :loading="loading"><a-table-column title="名称" data-index="name"/><a-table-column title="状态" data-index="status"/><a-table-column title="操作"><template #default="{record}"><a-button @click="showTask(record.id)">评测结果 / 报告</a-button></template></a-table-column></a-table><a-pagination :current="page" :total="total" :page-size="20" :show-size-changer="false" @change="refresh"/>
<a-modal :open="createOpen" :title="benchmarkMode?'创建单变量对照':'创建固定数据集评测'" :confirm-loading="createBusy" :mask-closable="false" :keyboard="false" @ok="create" @cancel="closeCreate"><a-alert v-if="assetError" type="warning" :message="assetError"/><a-button :loading="assetBusy" @click="loadAssets">刷新可用资产目录</a-button><a-form layout="vertical" :disabled="createBusy"><a-form-item label="名称"><a-input v-model:value="form.name" :maxlength="benchmarkMode?100:128"/></a-form-item><a-form-item label="数据集"><a-select :value="form.datasetId||undefined" show-search option-filter-prop="label" :options="datasetOptions.map(d=>({value:d.id,label:`${d.name} · ${d.id}`}))" @change="(id:string)=>chooseDataset(id)"/><a-pagination v-model:current="datasetPage" :total="datasetTotal" :page-size="20" :show-size-changer="false" @change="loadAssets"/></a-form-item><a-form-item label="精确冻结数据集版本"><a-select v-model:value="form.datasetVersion" :options="datasetVersions.map(d=>({value:d.versionNo,label:`v${d.versionNo} · ${d.sampleCount} 样本 · 修订 ${d.sourceDraftRevision}`}))"/><a-pagination :current="versionPage" :total="versionTotal" :page-size="20" :show-size-changer="false" @change="(p:number)=>chooseDataset(form.datasetId,p)"/></a-form-item><a-button @click="router.push('/evaluation/datasets')">查看数据集目录</a-button><a-form-item :label="benchmarkMode?'基线流水线':'流水线'"><a-select :value="form.pipelineId||undefined" show-search option-filter-prop="label" :options="pipelineOptions.map(d=>({value:d.id,label:`${d.name} · ${d.code}`}))" @change="choosePipeline"/><a-pagination v-model:current="pipelinePage" :total="pipelineTotal" :page-size="20" :show-size-changer="false" @change="loadAssets"/></a-form-item><a-form-item label="目标类型"><a-radio-group v-model:value="form.target" @change="updateTarget"><a-radio value="published">发布版本</a-radio><a-radio value="draft">精确草稿修订</a-radio></a-radio-group></a-form-item><a-form-item :label="form.target==='published'?'精确发布版本':'精确草稿修订'"><a-select v-if="form.target==='published'" v-model:value="form.targetVersion" :options="pipelineVersions.map(d=>({value:d.versionNo,label:`v${d.versionNo} · 修订 ${d.sourceDraftRevision}`}))"/><span v-else>当前已保存修订 {{pipelineDraft??'未加载'}}，创建时由服务端校验精确修订。</span></a-form-item><template v-if="benchmarkMode"><h4>候选版本</h4><a-form-item label="候选流水线"><a-select :value="candidateId||undefined" show-search option-filter-prop="label" :options="pipelineOptions.map(d=>({value:d.id,label:`${d.name} · ${d.code}`}))" @change="chooseCandidate"/></a-form-item><a-form-item label="候选目标类型"><a-radio-group v-model:value="candidateMode" @change="updateCandidate"><a-radio value="published">发布版本</a-radio><a-radio value="draft">当前已保存草稿</a-radio></a-radio-group></a-form-item><a-form-item label="候选精确版本"><a-select v-if="candidateMode==='published'" v-model:value="candidateVersion" :options="candidateVersions.map(d=>({value:d.versionNo,label:`v${d.versionNo} · 修订 ${d.sourceDraftRevision}`}))"/><span v-else>已保存草稿修订 {{candidateDraft??'未加载'}}</span></a-form-item><a-form-item label="唯一变化维度"><a-select v-model:value="dimension" :options="[{value:'PROMPT',label:'提示词'},{value:'MODEL',label:'模型（LLM主模型或专用模型）'},{value:'SKILL',label:'单个 Skill（提示槽位或独立API）'},{value:'FUSION',label:'融合政策'},{value:'PIPELINE',label:'完整 Pipeline 复合版本'}]"/></a-form-item><a-form-item v-if="needsNode" :label="dimension==='SKILL'?'双方相同的 LLM 或 Skill/API 节点':dimension==='MODEL'?'双方相同的 LLM 或专用模型节点':'双方相同的 LLM 节点'"><a-select v-model:value="variableNodeId" :options="baselineNodes.map(n=>({value:n.nodeId,label:`${n.name} · ${n.nodeId} · ${n.type}`}))"/></a-form-item><a-form-item v-if="dimension==='SKILL' && !standaloneSkill" label="Skill 在已发布智能体中的位置（从0开始）"><a-input-number v-model:value="skillSlot" :min="0" :precision="0"/></a-form-item><p v-if="standaloneSkill">独立Skill/API只有一个冻结Skill引用；比较其实际请求快照，工具、输入输出协议和其它政策须保持相同。无需Skill槽位。</p><p>两侧使用同一冻结数据集和并发。服务端拒绝多变量变化、没有有效变化和提示截断；Pipeline维度是复合版本比较。</p></template><a-form-item label="并发会话"><a-input-number v-model:value="form.concurrency" :min="1" :max="32" :precision="0"/></a-form-item></a-form><p>创建后手动执行；修改参数将生成新的请求标识，失败后原参数重试沿用原标识。</p></a-modal>
<BenchmarkReportPanel v-if="benchmarkBaselineId&&can('iqc:benchmark:view')" :baseline-task-id="benchmarkBaselineId"/><template v-if="selected"><h3>{{selected.name}} · {{selected.status}}</h3><a-space><a-select v-model:value="executionId" :options="rounds.map(r=>({value:r.id,label:`第 ${r.attemptNo} 轮 · ${r.status} · ${r.id}`}))" style="width:500px" :disabled="busy" @change="loadRound"/><a-button :loading="busy" @click="selectTask(selected.id)">刷新当前执行</a-button></a-space>
<template v-if="report"><a-alert :type="report.complete?'info':'warning'" :message="report.complete?'报告产物齐全（不代表质检达标或发布获准）':'报告不完整：缺失样本仍进入指标分母'"/><a-descriptions bordered :column="3"><a-descriptions-item label="冻结金标样本">{{report.expectedSamples}}</a-descriptions-item><a-descriptions-item label="已有产物">{{report.availableSamples}}</a-descriptions-item><a-descriptions-item label="执行成功">{{report.successfulSamples}}</a-descriptions-item><a-descriptions-item label="精确率">{{percent(report.findingMetrics.aggregate.precision)}}</a-descriptions-item><a-descriptions-item label="召回率">{{percent(report.findingMetrics.aggregate.recall)}}</a-descriptions-item><a-descriptions-item label="F1">{{percent(report.findingMetrics.aggregate.f1)}}</a-descriptions-item><a-descriptions-item label="事实覆盖率">{{percent(report.findingMetrics.aggregate.coverage)}}</a-descriptions-item><a-descriptions-item label="值准确率">{{percent(report.findingMetrics.aggregate.valueAccuracy)}}</a-descriptions-item><a-descriptions-item label="证据准确率">{{percent(report.findingMetrics.aggregate.evidenceAccuracy)}}</a-descriptions-item><a-descriptions-item label="分数 MAE">{{report.businessMetrics.meanAbsoluteScoreError??'无可比样本'}}</a-descriptions-item><a-descriptions-item label="分数覆盖率">{{percent(report.businessMetrics.scoreCoverage)}}</a-descriptions-item><a-descriptions-item label="高风险召回">{{percent(report.businessMetrics.highRiskRecall)}}</a-descriptions-item><a-descriptions-item label="标签准确率">{{percent(report.businessMetrics.labelAccuracy)}} · 可比 {{report.businessMetrics.comparableLabels}} / Gold {{report.businessMetrics.labelGold}}</a-descriptions-item><a-descriptions-item label="P50/P95/P99 毫秒">{{report.latencyMetrics.p50Ms??'—'}} / {{report.latencyMetrics.p95Ms??'—'}} / {{report.latencyMetrics.p99Ms??'—'}}</a-descriptions-item><a-descriptions-item label="已有产物执行失败率">{{percent(report.latencyMetrics.executionFailureRate)}}</a-descriptions-item><a-descriptions-item v-if="report.structuredMetrics" label="结构化输出成功率">{{report.structuredMetrics.declaredLlmNodes===0?'不适用（无 LLM 节点）':percent(report.structuredMetrics.successRate)}} · {{report.structuredMetrics.validOutputs}} / {{report.structuredMetrics.logicalInvocations}} · 未测量 {{report.structuredMetrics.unmeasuredAttempts}}</a-descriptions-item><a-descriptions-item v-if="report.regressionMetrics" label="回归通过率">{{percent(report.regressionMetrics.passRate)}} · {{report.regressionMetrics.passedSamples}} / {{report.regressionMetrics.expectedSamples}}</a-descriptions-item></a-descriptions>
<a-card v-if="report.inputCompletenessMetrics?.schemaVersion==='iqc-input-completeness-report-v1'" title="上游声明消息完整率" size="small" style="margin-top:16px">
 <a-alert type="info" show-icon message="按冻结金标中的上游清单声明比较消息数量。数量相等不证明内容没有遗漏或清单真实；没有显式清单声明时不填零。" />
 <a-descriptions :column="3" style="margin-top:12px">
  <a-descriptions-item label="测量覆盖">{{completenessPercent(report.inputCompletenessMetrics.measurementCoverage)}} · {{report.inputCompletenessMetrics.measuredSamples}} / {{report.inputCompletenessMetrics.expectedSamples}} 会话</a-descriptions-item>
  <a-descriptions-item label="数量完整会话率">{{completenessPercent(report.inputCompletenessMetrics.completeConversationRate)}} · {{report.inputCompletenessMetrics.completeSamples}} / {{report.inputCompletenessMetrics.measuredSamples}}</a-descriptions-item>
  <a-descriptions-item label="声明消息覆盖">{{completenessPercent(report.inputCompletenessMetrics.declaredMessageCoverage)}}</a-descriptions-item>
  <a-descriptions-item label="已测量样本预期 / 冻结消息">{{report.inputCompletenessMetrics.expectedMessages}} / {{report.inputCompletenessMetrics.observedMessages}}</a-descriptions-item>
  <a-descriptions-item label="不足会话 / 缺少消息">{{report.inputCompletenessMetrics.deficientSamples}} / {{report.inputCompletenessMetrics.missingMessages}}</a-descriptions-item>
  <a-descriptions-item label="超出会话 / 多余消息">{{report.inputCompletenessMetrics.excessSamples}} / {{report.inputCompletenessMetrics.extraMessages}}</a-descriptions-item>
  <a-descriptions-item label="未测量 / 其中无效清单">{{report.inputCompletenessMetrics.unmeasuredSamples}} / {{report.inputCompletenessMetrics.invalidManifestSamples}}</a-descriptions-item>
 </a-descriptions>
 <p>测量覆盖统计全部冻结金标输入，消息合计仅包含有效清单样本。尚未生成评测产物的样本仍计入；多余消息不抵消其它会话缺失，零测量分母显示未测量。</p>
</a-card>
<CitationGroundingPanel :metrics="report.citationGroundingMetrics" />
<ModelConsistencyPanel :task-id="report.taskId" :execution-id="report.executionId" :allowed="can('iqc:evaluation:report:view')" />
<a-card v-if="report.findingMetrics.confidenceDiagnostics?.schemaVersion==='iqc-finding-confidence-diagnostics-v1'" title="置信度误差诊断" size="small" style="margin-top:16px">
 <a-alert type="info" show-icon message="衡量带最终置信度的已知事实是否与冻结金标完整值匹配；不是正类概率，也不证明校准工件有效。缺少置信度、未知、错误及类型不符不填零，计入未测量。" />
 <a-descriptions :column="3" style="margin-top:12px">
  <a-descriptions-item label="测量覆盖">{{report.findingMetrics.confidenceDiagnostics.scored}} / {{report.findingMetrics.confidenceDiagnostics.eligibleKnownGold}} · {{percent(report.findingMetrics.confidenceDiagnostics.coverage)}}</a-descriptions-item>
  <a-descriptions-item label="未测量">{{report.findingMetrics.confidenceDiagnostics.unscored}}</a-descriptions-item>
  <a-descriptions-item label="Brier（越低越好）">{{report.findingMetrics.confidenceDiagnostics.brierScore??'无可测量样本'}}</a-descriptions-item>
  <a-descriptions-item label="ECE（越低越好）">{{percent(report.findingMetrics.confidenceDiagnostics.expectedCalibrationError)}}</a-descriptions-item>
 </a-descriptions>
 <a-table :data-source="report.findingMetrics.confidenceDiagnostics.bins" row-key="index" :pagination="false" size="small">
  <a-table-column title="置信度区间"><template #default="{record}">[{{percent(record.lowerInclusive)}}, {{percent(record.upperBound)}}{{record.upperInclusive?']':')'}}</template></a-table-column>
  <a-table-column title="事实数" data-index="count" />
  <a-table-column title="平均置信度"><template #default="{record}">{{percent(record.meanConfidence)}}</template></a-table-column>
  <a-table-column title="实际完整值准确率"><template #default="{record}">{{percent(record.observedAccuracy)}}</template></a-table-column>
 </a-table>
</a-card>

<p>耗时仅包含会话评测计算，排除排队、准备和落库；失败率不含缺失产物；结构化输出按逻辑 LLM 调用计数，旧轨迹或超时缺少记录时未测量，不是实际网络调用成功率。报告继承较早重试轮次的样本，下面列表仅显示选中执行轮次。</p><details><summary>按事实指标、计数、缺失样本及原执行来源</summary><pre>{{JSON.stringify(report,null,2)}}</pre></details></template>
<h3>当前执行轮次样本产物</h3><a-table :data-source="results" row-key="id" :pagination="false"><a-table-column title="样本" data-index="sampleId"/><a-table-column title="金标版本" data-index="sampleVersion"/><a-table-column title="状态" data-index="status"/><a-table-column title="耗时 ms" data-index="durationMs"/><a-table-column title="操作"><template #default="{record}"><a-button v-if="can('iqc:evaluation:result:view')" @click="viewResult(record)">实际轨迹 / 来源</a-button></template></a-table-column></a-table><a-pagination :current="resultPage" :total="resultTotal" :page-size="20" :show-size-changer="false" @change="(p:number)=>loadResults(p).catch(()=>message.error('产物分页加载失败'))"/><pre v-if="detail">{{detail}}</pre>
</template>
</template>
